const body = $input.first().json.body;
const status = body.status || '';
const previousStatus = body.previous_status || '';
const meetingTitle = body.title || 'Meeting';
const attendees = body.attendees || [];
const startTime = body.start_time ? new Date(body.start_time).toLocaleString('fr-FR', { timeZone: 'Africa/Tunis' }) : 'N/A';

const statusLabels = {
  planned: 'Planifié',
  in_progress: 'En cours',
  completed: 'Terminé',
  cancelled: 'Annulé'
};

const statusLabel = statusLabels[status] || status;
const previousStatusLabel = statusLabels[previousStatus] || previousStatus;

const subjectMap = {
  in_progress: `📢 Réunion démarrée : ${meetingTitle}`,
  completed: `✅ Réunion terminée : ${meetingTitle}`,
  cancelled: `❌ Réunion annulée : ${meetingTitle}`
};

const subject = subjectMap[status] || `Mise à jour de réunion : ${meetingTitle} (${previousStatusLabel} → ${statusLabel})`;

const htmlBody = `
<html><body>
  <h2>${subject}</h2>
  <p>Le statut de la réunion <b>${meetingTitle}</b> a changé :</p>
  <table style="border-collapse:collapse;">
    <tr><td style="padding:4px 12px;"><b>Statut précédent</b></td><td style="padding:4px 12px;">${previousStatusLabel}</td></tr>
    <tr><td style="padding:4px 12px;"><b>Nouveau statut</b></td><td style="padding:4px 12px;">${statusLabel}</td></tr>
    <tr><td style="padding:4px 12px;"><b>Heure de début</b></td><td style="padding:4px 12px;">${startTime}</td></tr>
  </table>
  <p style="margin-top:16px;">Connectez-vous à la plateforme pour plus de détails.</p>
</body></html>
`;

return attendees.map(email => ({
  json: {
    toEmail: email,
    subject: subject,
    html: htmlBody
  }
}));
